import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Variant5 {
    static int distinctColors(int[] arr, int start, int end) {
        boolean[] seenColors = new boolean[24];
        int count = 0;
        for (int i = start; i <= end; i++) {
            int color = arr[i];
            if (!seenColors[color]) {
                seenColors[color] = true;
                count++;
            }
        }
        return count;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int a = Integer.parseInt(st.nextToken());
        int b = Integer.parseInt(st.nextToken());
        int l = Integer.parseInt(st.nextToken()) - 1;
        int r = Integer.parseInt(st.nextToken()) - 1;

        int totalSegments = a + b;
        int repeatCount = 4;
        int[] patternArray = new int[totalSegments * repeatCount];

        int segmentShift = l / totalSegments;
        l -= segmentShift * totalSegments;
        r -= segmentShift * totalSegments;

        int segmentSize = (r - l + 1) / totalSegments;
        if (segmentSize > 2) {
            r -= (segmentSize - 2) * totalSegments;
        }

        int diffVal = a > b ? a - b : 1;
        for (int rep = 0; rep < repeatCount; rep++) {
            for (int k = 0; k < a - diffVal; k++)
                patternArray[(a + b) * rep + k] = k;
            for (int k = 0; k < diffVal; k++)
                patternArray[(a + b) * rep + a - diffVal + k] = (rep % 2 == 0) ? a - diffVal + k : a + k;
        }

        int minColorsCount = a + a;
        for (int shiftA = 1; shiftA <= diffVal; shiftA++) {
            for (int k = 0; k < b; k++)
                patternArray[(a + b) * 0 + a + k] = patternArray[(a + b) * 0 + a - shiftA];
            for (int shiftB = 1; shiftB <= diffVal; shiftB++) {
                for (int k = 0; k < b; k++)
                    patternArray[(a + b) * 1 + a + k] = patternArray[(a + b) * 1 + a - shiftB];
                for (int shiftC = 1; shiftC <= diffVal; shiftC++) {
                    for (int k = 0; k < b; k++)
                        patternArray[(a + b) * 2 + a + k] = patternArray[(a + b) * 2 + a - shiftC];
                    for (int k = 0; k < b; k++)
                        patternArray[(a + b) * 3 + a + k] = patternArray[(a + b) * 3 + a - shiftC];
                    minColorsCount = Math.min(minColorsCount, distinctColors(patternArray, l, r));
                }
            }
        }
        System.out.println(minColorsCount);
    }
}
